    /**
     * Test Case 1: Method is not DEFLATED.
     * Should return immediately without writing anything.
     */
    @Test
    public void testWriteDataDescriptor_NotDeflated() throws IOException {
        ZipArchiveEntry ze = mock(ZipArchiveEntry.class);
        when(ze.getMethod()).thenReturn(ZipEntry.STORED);

        zos.writeDataDescriptor(ze);

        assertEquals(0, out.size());
    }

