    /**
     * Test Case 3: DEFLATED and channel is null, and NO Zip64 extra.
     * Should write DD_SIG, CRC (ZipLong), CompressedSize (ZipLong), and Size (ZipLong).
     */
    @Test
    public void testWriteDataDescriptor_DeflatedNoZip64() throws IOException {
        ZipArchiveEntry ze = mock(ZipArchiveEntry.class);
        when(ze.getMethod()).thenReturn(ZipEntry.DEFLATED);
        when(ze.getCrc()).thenReturn(12345L);
        when(ze.getCompressedSize()).thenReturn(67890L);
        when(ze.getSize()).thenReturn(112233L);

