    public void testWriteDataDescriptor_SequenceVerification() throws IOException {
        ZipArchiveEntry ze = mock(ZipArchiveEntry.class);
        when(ze.getMethod()).thenReturn(ZipEntry.DEFLATED);
        when(ze.getCrc()).thenReturn(1L);
        when(ze.getCompressedSize()).thenReturn(2L);
